-- The Mongo object id is generated by the client and has no ClickHouse counterpart, so an `_id`
-- of an inserted document is dropped rather than written: a driver adds one to every document it
-- sends, and a table of documents does not have a column for it. Only the top level `_id` is the
-- object id; a field of that name inside a subdocument is an ordinary field.
--
-- The comments have to stay out of the `mongo` dialect: there a comment is part of the query text.

SET dialect='clickhouse';

DROP TABLE IF EXISTS docs;
CREATE TABLE docs (id Int32, name String, `profile._id` String) ENGINE = MergeTree ORDER BY id;

SET allow_experimental_mongo_dialect = 1;
SET dialect='mongo';
db.docs.insertOne({"_id" : {"$oid" : "64c9c5b1e1b8a2b3c4d5e6f7"}, "id" : 1, "name" : "alpha", "profile" : {"_id" : "nested"}});
SET dialect='clickhouse';
SELECT id, name, `profile._id` FROM docs ORDER BY id;

SET allow_experimental_mongo_dialect = 1;
SET dialect='mongo';
db.docs.insertMany([{"_id" : 2, "id" : 2, "name" : "beta", "profile" : {"_id" : ""}}, {"id" : 3, "name" : "gamma", "profile" : {"_id" : ""}}]);
SET dialect='clickhouse';
SELECT id, name FROM docs ORDER BY id;

DROP TABLE docs;
